-- 00-base-navigation.sql (appended by sveltebuilder sync:supabase)
-- ============================================================
-- Navigation items for the admin area
-- Depends on: local_text_link entries generated by sveltebuilder sync:supabase
--
-- The settings items sort after every newsroom item (100+) because the admin layout
-- pulls them into the collapsible "Application settings" group, and the newsroom
-- links stay top level. Which hrefs belong to the group, and each item's icon, is
-- decided in src/routes/(admin)/admin-navigation.ts.

insert into public.navigation_item (local_text_link_id, href, scope, sort_order)
select l.id, nav.href, nav.scope, nav.sort_order
from (values
  ('admin.nav.dashboard',      '/admin/dashboard',       'admin', 10),
  ('admin.nav.local_text',     '/admin/local-text',      'admin', 120),
  ('admin.nav.locale',         '/admin/locale',          'admin', 130),
  ('admin.nav.navigation_item','/admin/navigation-item', 'admin', 140)
) as nav(slug, href, scope, sort_order)
join public.local_text_link l
  on l.slug = nav.slug and l.scope is null and l.entity_id is null
on conflict (href, scope) do nothing;

